using Astronomy.MediaFactory.Core.DocumentaryBlueprint;using Astronomy.MediaFactory.ProductionAdapters;using Microsoft.Extensions.Options;using Xunit;
namespace Astronomy.MediaFactory.Tests.ProductionAdapters;
public sealed class DocumentaryMediaVerificationDeterminismTests {
 static DocumentaryMediaVerificationRequest Request()=>new("scene",DocumentaryMediaAssetType.SceneVideo,DocumentaryMediaAssetFormat.Mp4,DocumentaryPhysicalArtifactKind.SceneVideo,"c",1,ExpectedDurationMilliseconds:2000,ExpectedWidth:1920,ExpectedHeight:1080,ExpectedFrameRate:30,RequireVideo:true);
 [Fact] public void Same_request_resolves_same_policy_id(){var p=new DocumentaryMediaVerificationPolicyResolver();Assert.Equal(p.Resolve(Request()).PolicyId,p.Resolve(Request()).PolicyId);}
 [Fact] public void Same_probe_result_produces_same_evidence(){var r=Request();var a=new DocumentaryPhysicalArtifactDescriptor("scene","sha256:"+new string('a',64),"/final/a","video/mp4",1,new string('a',64),2000,1920,1080,30,null,null,"p",1,"c");var p=new DocumentaryMediaProbeResult(true,2200,true,false,false,1920,1080,30,ContainerFormat:"mp4");var resolver=new DocumentaryMediaVerificationPolicyResolver();var e=new DocumentaryMediaVerificationEvaluator(Options.Create(new DocumentaryMediaVerificationAdapterOptions()));Assert.Equal(e.Evaluate(r,a,p,resolver.Resolve(r)),e.Evaluate(r,a,p,resolver.Resolve(r)));}
 [Fact] public async Task Same_artifact_produces_same_diagnostic_filename(){await using var f=await DocumentaryMediaVerificationAdapterFixture.NarrationAudio();var one=await f.Adapter.VerifyAsync(f.Request,f.ExecutionContext,f.AttemptContext,f.Workspace,default);var two=await f.Adapter.VerifyAsync(f.Request,f.ExecutionContext,f.AttemptContext,f.Workspace,default);Assert.Equal(one.ProviderDiagnosticsReference,two.ProviderDiagnosticsReference);}
}
